<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { Close, Download, Plus, Refresh, Search } from '@element-plus/icons-vue'
import { workflowApi, type ExportJob } from '../api'
import { bytes, dateTime, errorMessage, timeRange } from '../lib/format'
import { usePaged } from '../composables/usePaged'
import { useAction } from '../composables/useAction'
import PageHeader from '../components/PageHeader.vue'
import StatusBadge from '../components/StatusBadge.vue'
import ChannelPicker from '../components/ChannelPicker.vue'
const { busy, run, confirm } = useAction(), dialog = ref(false), channelId = ref<number>(), range = ref<[Date, Date] | null>(null)
const { items, total, page, pageSize, search, loading, error, load } = usePaged(workflowApi.exports, undefined, ['export.changed', 'access.changed'])
async function create() { if (await run(async () => { if (!channelId.value) throw new Error('请选择导出通道'); const time = timeRange(range.value, 24); await workflowApi.createExport(channelId.value, time.start, time.end); await load(true) }, '导出任务已提交')) dialog.value = false }
async function cancel(job: ExportJob) { await confirm(`取消“${job.channelName}”的导出任务？`, async () => { await workflowApi.cancelExport(job.id); await load() }, '任务已取消') }
async function retry(job: ExportJob) { await run(async () => { await workflowApi.retryExport(job.id); await load() }, '任务已重新排队') }
function expired(job: ExportJob) { return !!job.expiresAt && Date.parse(job.expiresAt) <= Date.now() }
let timer: ReturnType<typeof setInterval>
onMounted(() => { timer = setInterval(() => { if (items.value.some(job => ['running', 'queued'].includes(job.state)) && !loading.value) void load() }, 10000) })
onBeforeUnmount(() => clearInterval(timer))
</script>
<template><div><PageHeader title="录像导出" :count="total"><el-button :icon="Refresh" :loading="loading" @click="load()">刷新</el-button><el-button type="primary" :icon="Plus" @click="dialog = true">新建导出</el-button></PageHeader><form class="filter-bar" @submit.prevent="load(true)"><el-input v-model="search" clearable :prefix-icon="Search" placeholder="搜索导出任务" aria-label="搜索导出任务" @clear="load(true)" /><el-button native-type="submit" :icon="Search">查询</el-button></form><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-table v-loading="loading" :data="items" empty-text="暂无导出任务"><el-table-column prop="channelName" label="通道" min-width="140" /><el-table-column label="录像时段" min-width="190"><template #default="{ row }"><div>{{ dateTime(row.start) }}</div><div class="muted">{{ dateTime(row.end) }}</div></template></el-table-column><el-table-column label="状态" width="112"><template #default="{ row }"><StatusBadge :value="row.state" /></template></el-table-column><el-table-column label="进度" min-width="170"><template #default="{ row }"><el-progress :percentage="Math.max(0, Math.min(100, Math.round(row.progress)))" :status="row.state === 'failed' ? 'exception' : row.state === 'completed' ? 'success' : undefined" /><small v-if="row.error" class="field-error">{{ errorMessage(row.error) }}</small></template></el-table-column><el-table-column label="文件大小" width="110"><template #default="{ row }">{{ row.fileSize ? bytes(row.fileSize) : '—' }}</template></el-table-column><el-table-column label="保留至" min-width="168"><template #default="{ row }">{{ dateTime(row.expiresAt) }}</template></el-table-column><el-table-column label="操作" width="116" fixed="right"><template #default="{ row }"><a v-if="row.state === 'completed' && !expired(row as ExportJob)" :href="workflowApi.exportUrl(row.id)" class="download-link"><el-icon><Download /></el-icon>下载</a><span v-else-if="row.state === 'completed'" class="muted">已过期</span><el-button v-if="['queued', 'running'].includes(row.state)" link type="danger" :icon="Close" :disabled="busy" @click="cancel(row as ExportJob)">取消</el-button><el-button v-if="['failed', 'cancelled'].includes(row.state)" link type="primary" :icon="Refresh" :disabled="busy" @click="retry(row as ExportJob)">重试</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[20,50,100]" layout="total, sizes, prev, pager, next" @current-change="load()" @size-change="load(true)" /></div><el-dialog v-model="dialog" title="新建录像导出" width="560px"><el-form label-position="top"><el-form-item label="通道" required><ChannelPicker v-model="channelId" /></el-form-item><el-form-item label="录像时间（最长 24 小时）" required><el-date-picker v-model="range" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间" format="YYYY-MM-DD HH:mm:ss" /></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="busy" @click="create">提交导出</el-button></template></el-dialog></div></template>
